<script setup lang="ts">
import {ref,nextTick,onMounted,onBeforeUnmount,watch} from 'vue'
import {floatingPosition} from '../lib/readerPresentation'
import Icon from './AppIcon.vue'
const props=defineProps<{selection:{page:number;quote:string;anchor?:{left:number;right:number;top:number;bottom:number}};container?:HTMLElement}>()
const emit=defineEmits<{action:[id:string];dismiss:[]}>()
const bar=ref<HTMLElement>(),menu=ref<HTMLElement>(),moreButton=ref<HTMLButtonElement>(),more=ref(false),visible=ref(true),position=ref({left:'8px',top:'8px'}),menuPosition=ref({left:'8px',top:'8px'})
let resizeObserver:ResizeObserver|undefined
const items=[{id:'underline',label:'划线'},{id:'comment',label:'评论'},{id:'translate',label:'翻译'},{id:'excerpt',label:'保存摘录'},{id:'formula',label:'解释公式'},{id:'table',label:'分析表格'}]
function place(){const area=props.container,page=area?.querySelector<HTMLElement>('[data-page="'+props.selection.page+'"]');if(!area||!page||!bar.value)return;const clip=area.getBoundingClientRect(),p=page.getBoundingClientRect(),a=props.selection.anchor;const anchor=a?{left:p.left+a.left,right:p.left+a.right,top:p.top+a.top,bottom:p.top+a.bottom}:{left:p.left,right:p.right,top:Math.max(p.top,clip.top),bottom:Math.min(p.bottom,clip.bottom)-60};visible.value=p.bottom>clip.top&&p.top<clip.bottom;if(!visible.value){more.value=false;return}const bounded={...anchor,top:Math.max(clip.top,anchor.top),bottom:Math.min(clip.bottom,anchor.bottom)};const xy=floatingPosition(bounded,bar.value.offsetWidth,bar.value.offsetHeight,{left:Math.max(0,clip.left),right:Math.min(innerWidth,clip.right),top:clip.top,bottom:Math.min(innerHeight,clip.bottom)});position.value={left:xy.left+'px',top:xy.top+'px'};if(more.value&&menu.value&&moreButton.value){const xy=floatingPosition(moreButton.value.getBoundingClientRect(),menu.value.offsetWidth,menu.value.offsetHeight,{left:0,right:innerWidth,top:0,bottom:innerHeight});menuPosition.value={left:xy.left+'px',top:xy.top+'px'}}}
async function toggle(){more.value=!more.value;if(more.value){await nextTick();place();menu.value?.querySelector('button')?.focus()}}
function close(focus=true){more.value=false;if(focus)moreButton.value?.focus()}
function outside(e:PointerEvent){if(!menu.value?.contains(e.target as Node)&&!bar.value?.contains(e.target as Node))close(false)}
function key(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();if(more.value)close();else emit('dismiss')}else if(more.value&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const buttons=[...menu.value!.querySelectorAll('button')],i=buttons.indexOf(document.activeElement as HTMLButtonElement);buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}else if(more.value&&e.key==='Tab')close(false)}
watch(()=>props.selection,()=>{more.value=false;void nextTick(place)},{deep:true})
onMounted(()=>{void nextTick(place);if(props.container){resizeObserver=new ResizeObserver(place);resizeObserver.observe(props.container)}window.addEventListener('scroll',place,true);window.addEventListener('resize',place);document.addEventListener('pointerdown',outside,true);document.addEventListener('keydown',key)})
onBeforeUnmount(()=>{resizeObserver?.disconnect();window.removeEventListener('scroll',place,true);window.removeEventListener('resize',place);document.removeEventListener('pointerdown',outside,true);document.removeEventListener('keydown',key)})
</script>
<template><Teleport to="body"><div v-show="visible" ref="bar" class="reader-selection-tools" :style="position" role="toolbar" aria-label="原文选区操作"><button type="button" @click="emit('action','highlight')"><Icon name="Highlighter" :size="14"/>高亮</button><button type="button" @click="emit('action','explain')">解释</button><button type="button" @click="emit('action','ask')"><Icon name="Sparkles" :size="14"/>问 AI</button><button ref="moreButton" type="button" aria-haspopup="menu" :aria-expanded="more" @click="toggle">更多<Icon name="ChevronDown" :size="12"/></button><button type="button" aria-label="取消选区" @click="emit('dismiss')"><Icon name="X" :size="13"/></button></div><div v-if="more" ref="menu" class="reader-selection-menu" :style="menuPosition" role="menu" aria-label="更多选区操作"><button v-for="item in items" :key="item.id" type="button" role="menuitem" @click="close(false);emit('action',item.id)">{{item.label}}</button></div></Teleport></template>
<style scoped>
.reader-selection-tools,.reader-selection-menu{position:fixed;z-index:120;background:var(--surface-raised);border:1px solid var(--border);border-radius:10px;box-shadow:0 4px 16px #322e3b0d;color:var(--text)}.reader-selection-tools{display:flex;align-items:center;padding:4px;gap:2px;max-width:calc(100vw - 16px)}.reader-selection-tools button{display:flex;align-items:center;gap:4px;padding:7px 8px;font-size:12px;white-space:nowrap;border-radius:6px;transition:background 150ms}.reader-selection-menu{width:170px;padding:5px;max-height:calc(100dvh - 16px);overflow:auto}.reader-selection-menu button{display:block;width:100%;padding:8px 10px;text-align:left;font-size:12px;border-radius:5px}.reader-selection-tools button:hover,.reader-selection-menu button:hover{background:var(--surface-hover)}
</style>
